function room(){return roomDefinitions.find(r=>r.id===S().room);}
function roomMembers(){return room().members.map(byId).filter(a=>scopeAgents().some(w=>w.id===a.id));}
function renderRooms(){const r=room(),rs=S().roomStates[r.id],members=roomMembers(),main=members.slice(0,3);return frame(5,`<section class="rooms-layout"><nav class="room-tabs" aria-label="${tr('并行目标','Parallel goals')}">${roomDefinitions.map((g,i)=>`<button data-room="${g.id}" aria-pressed="${g.id===r.id}"><span class="room-index">0${i+1}</span><div><strong>${l(g.title)}</strong><small>${g.members.length} Agent${S().roomStates[g.id].draft?' · '+t('draft'):''}</small></div>${g.id===r.id?icon('arrow'):''}</button>`).join('')}<button class="new-room-work" data-action="new-command">${icon('plus')}${t('newTask')}</button></nav><div class="room-body"><aside class="room-agenda"><span class="overline">${tr('这次要达成的事','THE OBJECTIVE')}</span><h2>${l(r.title)}</h2><p>${l(r.goal)}</p><div class="room-participants">${avatarStack(members)}<span>${members.length} ${tr('位参与者','participants')}</span></div><section><h3>${tr('交付检查点','Checkpoints')}</h3><div class="agenda-step"><i></i>${tr('把问题和范围说清楚','Agree on the scope')}</div><div class="agenda-step"><i></i>${tr('各自处理，交叉验证','Execute and cross-check')}</div><div class="agenda-step"><i></i>${tr('你确认最终结果','You review the result')}</div></section><div class="room-principle">${icon('link')}<p>${tr('一个目标，一个上下文。切到其他房间，草稿仍留在这里。','One goal, one context. Your draft stays here when you switch rooms.')}</p></div></aside><div class="room-conversation"><header><div>${orb}<div><strong>${tr('Norma 协调中','Norma is coordinating')}</strong><small>${tr('各位的原卡片继续独立运行','Original agent cards continue independently')}</small></div></div><button class="icon-button" data-action="room-roster" aria-label="${tr('查看所有 Agent','View all agents')}">${icon('people')}</button></header><div class="room-feed"><div class="room-day">${tr('今天 · 09:41','TODAY · 09:41')}</div><article class="norma-turn"><div>${orb}<b>Norma</b><span>${tr('协调建议','Coordination')}</span></div><p>${tr('我把这个目标需要的 Agent 放在了一起。你可以给大家定方向，也可以只回复其中一位。','The agents for this goal are together here. Set a shared direction, or speak directly to one person.')}</p></article>${main.map(a=>`<article class="room-agent-turn"><div>${av(a)}<b>${a.agent}</b><span>${projects[a.project].name}</span>${status(a)}</div><p>${esc(l(a.answer))}</p><button class="text-button" data-chat="${a.id}">${tr('继续这位 Agent 的原会话','Continue this agent’s original session')}${icon('arrow')}</button></article>`).join('')}${rs.events.map(e=>`<div class="room-user-turn"><span>${t('you')} → ${esc(e.names)}</span><p>${esc(e.text)}</p></div>`).join('')}</div><form class="room-composer" data-room-form><div class="room-targets"><span>${tr('发给','To')}</span><button type="button" data-room-target="norma" aria-pressed="${rs.target==='norma'}">${orb}${tr('Norma 协调全组','Norma · whole group')}</button>${members.map(a=>`<button type="button" data-room-target="${a.id}" aria-pressed="${rs.target===a.id}">${av(a)}${a.agent}</button>`).join('')}</div><div><textarea rows="2" data-testid="room-input" placeholder="${tr('在这个目标里继续讨论，或调整大家的方向…','Continue this goal or adjust the team’s direction…')}">${esc(rs.draft)}</textarea><button type="submit" class="send-circle" data-testid="room-send" aria-label="${t('preview')}">${icon('up')}</button></div><small>${tr('发送前会列出实际接收者 · 每个目标的草稿独立保留','Review actual recipients before sending · Drafts stay with each goal')}</small></form></div><aside class="room-members"><div><h3>${tr('参与这件事','On this goal')}</h3><span>${members.length}</span></div>${members.map(a=>`<article><div>${av(a)}<button data-chat="${a.id}">${a.agent}</button>${status(a)}</div><p>${esc(l(a.summary))}</p><button class="text-button" data-room-target="${a.id}">${tr('只发给他','Direct message')}${icon('arrow')}</button></article>`).join('')||`<p class="empty">${t('empty')}</p>`}</aside></div></section>`);}
